# Search for any yield data in the JSON
import re

def search_json(obj, path=""):
    if isinstance(obj, dict):
        for key, value in obj.items():
            search_json(value, f"{path}.{key}")
    elif isinstance(obj, list):
        for i, item in enumerate(obj):
            search_json(item, f"{path}[{i}]")
    elif isinstance(obj, str):
        # Look for yield patterns
        if re.search(r'1[0-4]\.\d{2}', obj) and 'Treasury' in obj:
            print(f"{path}: {obj[:200]}")

